import java.io.*;import java.nio.file.*;import java.util.*;import java.util.zip.*;import ij.gui.*;import ij.process.*;
public class ReviewNative40Outlier {
 static class O{int w,h;float[]x,y;}
 static O load(String path)throws Exception{try(DataInputStream d=new DataInputStream(new GZIPInputStream(Files.newInputStream(Path.of(path))))){if(d.readInt()!=0x47415450||d.readInt()!=1)throw new AssertionError();int w=d.readInt(),h=d.readInt(),count=d.readInt();O found=null;for(int k=0;k<count;k++){float cx=d.readFloat(),cy=d.readFloat();int n=d.readInt();float[]x=new float[n],y=new float[n];for(int j=0;j<n;j++){x[j]=d.readFloat();y[j]=d.readFloat();}if(cx==606.5f&&cy==510.5f){found=new O();found.w=w;found.h=h;found.x=x;found.y=y;}}if(d.read()!=-1||found==null)throw new AssertionError();return found;}}
 static byte[] mask(O o){ByteProcessor p=new ByteProcessor(o.w,o.h);p.setValue(255);p.fill(new PolygonRoi(o.x,o.y,o.x.length,Roi.POLYGON));return(byte[])p.getPixels();}
 static String stats(byte[]a,int w){long n=0,sx=0,sy=0,per=0;int minx=w,miny=a.length/w,maxx=0,maxy=0;for(int i=0;i<a.length;i++)if(a[i]!=0){int x=i%w,y=i/w;n++;sx+=x;sy+=y;minx=Math.min(minx,x);miny=Math.min(miny,y);maxx=Math.max(maxx,x);maxy=Math.max(maxy,y);if(x==0||a[i-1]==0)per++;if(x==w-1||a[i+1]==0)per++;if(y==0||a[i-w]==0)per++;if(i+w>=a.length||a[i+w]==0)per++;}return "area="+n+" centroid_x="+((double)sx/n+.5)+" centroid_y="+((double)sy/n+.5)+" perimeter4="+per+" bbox="+minx+","+miny+","+maxx+","+maxy;}
 public static void main(String[]args)throws Exception{O old=load(args[0]),now=load(args[1]);if(old.w!=now.w||old.h!=now.h||old.x.length!=now.x.length)throw new AssertionError();byte[]a=mask(old),b=mask(now);System.out.println("scope=single independent polygon, center606.5,510.5; not original exclusive label map");System.out.println("legacy "+stats(a,old.w));System.out.println("modern "+stats(b,now.w));long diff=0,inter=0,union=0;for(int i=0;i<a.length;i++){if(a[i]!=0&&b[i]!=0)inter++;if(a[i]!=0||b[i]!=0)union++;if(a[i]!=b[i]){diff++;System.out.println("changed_pixel x="+i%old.w+" y="+i/old.w+" legacy="+(a[i]&255)+" modern="+(b[i]&255));}}System.out.println("different_pixels="+diff+" intersection="+inter+" union="+union+" IoU="+((double)inter/union));for(int k=0;k<old.x.length;k++)if(old.x[k]!=now.x[k]||old.y[k]!=now.y[k])System.out.println("vertex="+k+" legacy="+old.x[k]+","+old.y[k]+" modern="+now.x[k]+","+now.y[k]);if(diff!=1||inter!=690||union!=691)throw new AssertionError("Unexpected outlier");}
}
